@app.route(&#x27;/login&#x27;, methods=[&#x27;GET&#x27;, &#x27;POST&#x27;])
def login():
    if request.method == &#x27;POST&#x27;:
        username = request.form.get(&#x27;username&#x27;)
        password = request.form.get(&#x27;password&#x27;)
        user = User.query.filter_by(username=username).first()
        if user and bcrypt.check_password_hash(user.password, password):
            login_user(user)
            return redirect(url_for(&#x27;index&#x27;))
        else:
            flash(&#x27;Login Unsuccessful. Please check username and password&#x27;, &#x27;danger&#x27;)
    return render_template(&#x27;login.html&#x27;)

@app.route(&#x27;/logout&#x27;)
@login_required
def logout():
    logout_user()
    return redirect(url_for(&#x27;login&#x27;))

@app.route(&#x27;/add_sales_rep&#x27;, methods=[&#x27;POST&#x27;])
@login_required
def add_sales_rep():
    name = request.form.get(&#x27;name&#x27;)
    new_rep = SalesRep(name=name)
    db.session.add(new_rep)
    db.session.commit()
    return redirect(url_for(&#x27;index&#x27;))

@app.route(&#x27;/add_deal/&lt;int:sales_rep_id&gt;&#x27;, methods=[&#x27;POST&#x27;])
@login_required
def add_deal(sales_rep_id):
    description = request.form.get(&#x27;description&#x27;)
    value = request.form.get(&#x27;value&#x27;)
    vehicle = request.form.get(&#x27;vehicle&#x27;)
    trade_in = request.form.get(&#x27;trade_in&#x27;)
    new_deal = Deal(description=description, value=value, vehicle=vehicle, trade_in=trade_in, sales_rep_id=sales_rep_id)
    db.session.add(new_deal)
    db.session.commit()
    return redirect(url_for(&#x27;index&#x27;))

@app.route(&#x27;/sales_rep/&lt;int:id&gt;&#x27;)
@login_required
def sales_rep(id):
    sales_rep = SalesRep.query.get_or_404(id)
    return render_template(&#x27;sales_rep.html&#x27;, sales_rep=sales_rep)

if __name__ == &#x27;__main__&#x27;:
    db.create_all()
    app.run(debug=True)
